    "tasks": {
      "type": "array",
      "description": "One subagent per item",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Stable id base ([A-Za-z0-9_-]); uniquified per session"
          },
          "agent": {
            "type": "string",
            "description": "Agent type for this item (see the tool description); omit for the general-purpose worker"
          },
          "task": {
            "type": "string",
            "description": "Complete, self-contained instructions for the subagent"
          },
          "outputSchema": {
            "description": "JSON Schema the subagent's final output must satisfy; invalid output gets one fix retry, then the item fails"
          }
        },
        "required": [
          "task"
        ]
      }
    },
    "background": {
      "type": "boolean",
      "description": "Run items as background jobs and return job ids immediately (default: host configuration)"
    }
  },
  "required": [
    "context",
    "tasks"
  ]
}

{
  "type": "object",
  "properties": {
    "goal": {
      "type": "string",
      "description": "Investigation goal for this checkpoint"
    }
  }
}

{
  "type": "object",
  "properties": {
    "report": {
      "type": "string",
      "description": "Investigation findings retained after the rewind"
    }
  },
  "required": [
    "report"
  ]
}

{
  "type": "object",
  "properties": {
    "target": {
      "type": "string",
      "description": "Numeric id or range from a context marker, e.g. \"5\" or \"2-6\". Omit to list the hidden-segment index."
    },
    "action": {
      "type": "string",
      "description": "Tier 2 segment management (issue #1379). With a target: \"hide\" folds a dead-weight segment into its expandable marker right now, without waiting for pressure; \"pin\" shields a segment from every hide/compact path; \"unpin\" releases it. Omit to expand the target."
    },
    "query": {
      "type": "string",
      "description": "Search the hidden segments (preview and full content) when you know WHAT you need but not the id. Free — no budget."
    },
    "page": {
      "type": "integer",
      "description": "1-based page for giant segments (default 1)",
      "minimum": 1
    }
  },
  "required": []
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The phrase to search for (keyword, or a regular expression with regex: true). Required in search mode."
    },
    "scope": {
      "type": "string",
      "enum": [
        "branch",
        "tree"
      ],
      "description": "branch (default) searches the active branch only; tree spans forks and abandoned branches too."
    },
    "mode": {
      "type": "string",
      "enum": [
        "search",
        "map"
      ],
      "description": "search (default) finds records; map reports the archive structure (counts, hidden totals, checkpoint tree)."
    },
    "kinds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Only these record types (message, compaction, compact_checkpoint, custom, …). Empty keeps every kind."
    },
    "before": {
      "type": "string",
      "description": "Only records older than this ISO-8601 instant."
    },
    "after": {
      "type": "string",
      "description": "Only records newer than this ISO-8601 instant."
    },
    "regex": {
      "type": "boolean",
      "description": "Match query as a case-insensitive regular expression (default: literal keyword)."
    },
    "maxHits": {
      "type": "integer",
      "description": "Cap on returned pointers (default 40, max 200). A capped scan returns a continuation token."
    },
    "continuation": {
      "type": "integer",
      "description": "The token a previous capped call returned — resumes the scan after the records already examined."
    }
  }
}

content.text:
  /// The deduped (keep-first) entry list.
  final List<ProviderQueueEntry> entries;

  /// Non-fatal notes (unknown provider_config keys carried as params).
  final List<String> warnings;
}

/// Parses the queue entries from an already-decoded JSON/YAML list.
///
/// Strict per-entry validation (candidate-listing errors), keep-first
/// dedup with a warning, and `{"ref": ...}` resolution through
/// [resolveRef]. An empty list is an explicit error ("queue empty" —
/// UT-parse-empty-single): a queue must have at least one entry.
ParsedProviderQueue parseProviderQueueEntries(
  Object? node, {
  required String source,
  ({String kind, String? baseUrl, String model, String? keyName})? Function(
    String name,
  )?
  resolveRef,
}) {
  if (node is! List) {
    throw ConfigException(
      '$source: expected an array of '
      '{"provider_type", "provider_config"} entries, got ${_typeName(node)}',
    );
  }
  if (node.isEmpty) {
    throw ConfigException(
      '$source: the queue is empty — provide at least one entry or unset '
      'the queue to use the legacy provider/model configuration',
    );
  }
  final warnings = <String>[];
  final entries = <ProviderQueueEntry>[];
  final seen = <String>{};
  for (var i = 0; i < node.length; i++) {
    final item = node[i];
    if (item is! Map) {
      throw ConfigException(
        '$source: queue entry #${i + 1} must be an object, '
        'got ${_typeName(item)}',
      );
    }
    final ProviderQueueEntry entry;
    if (item['ref'] is String) {
      if (resolveRef == null) {
        throw ConfigException(
          '$source: queue entry #${i + 1} uses {"ref": ...} but this '
          'source has no customProviders registry to resolve against',
        );
      }
      entry = ProviderQueueEntry.resolvedRef(
        name: item['ref'] as String,
        position: i + 1,
        resolveRef: resolveRef,
        overrides: item['provider_config'] is Map
            ? (item['provider_config'] as Map).cast<Object?, Object?>()
            : null,
      );

  final entry = next.removeAt(index);
  next.insert(newIndex, entry);
  return next;
}

/// Serializes [entries] to the yaml body of a `providersQueue:` block
/// (2-space indented list items, no trailing newline) — the surgical
/// write's payload (UT-yaml-roundtrip). Secrets cannot leak: the shape
/// only carries `apiKeyEnv` names.
String providersQueueYamlBody(List<ProviderQueueEntry> entries) {
  final buffer = StringBuffer();
  for (final entry in entries) {
    buffer.writeln('- provider_type: ${entry.providerType}');
    buffer.writeln('  provider_config:');
    buffer.writeln('    model: ${entry.model}');
    if (entry.baseUrl != null) buffer.writeln('    baseUrl: ${entry.baseUrl}');
    if (entry.apiKeyEnv != null) {
      buffer.writeln('    apiKeyEnv: ${entry.apiKeyEnv}');
    }
    if (entry.contextWindow != null) {
      buffer.writeln('    contextWindow: ${entry.contextWindow}');
    }
    if (entry.maxTokens != null) {
      buffer.writeln('    maxTokens: ${entry.maxTokens}');
    }
  }
  return buffer.toString().trimRight();
}

String _typeName(Object? value) => switch (value) {
  null => 'nothing',
  String() => 'a string',
  int() || double() => 'a number',
  bool() => 'a boolean',
  Map() => 'an object',
  List() => 'an array',
  _ => value.runtimeType.toString(),
};

String _quote(String path) => "'$path'";

String? _optionalString(Map<Object?, Object?> map, String key, String where) {
  final value = map[key];
  if (value == null) return null;
  if (value is! String || value.trim().isEmpty) {
    throw ConfigException('$where: "$key" must be a non-empty string');
  }
  return value.trim();
}

int? _optionalInt(Map<Object?, Object?> map, String key, String where) {
  final value = map[key];
  if (value == null) return null;
  if (value is! int || value <= 0) {
    throw ConfigException('$where: "$key" must be a positive integer');
  }
  return value;
}

int _lineOf(String text, int offset) =>
    text.substring(0, offset).split('\n').length;

