    // iOS: open the app's settings page (user navigates to the permission).
    url = 'app-settings:';
  }
  unawaited(
    url_launcher.launchUrl(
      Uri.parse(url),
      mode: url_launcher.LaunchMode.externalApplication,
    ),
  );
}

